const updateFacilityCheckin = `-- name: UpdateFacilityCheckin :one
UPDATE facility_checkin
SET
    printed_qr    = $1,
    entry_code    = $2,
    radius_m      = $3,
    flash_booking = $4,
    staff_confirm = $5,
    qr_reader     = $6,
    staff_contacts = $7,
    -- kept while any phone or staff way stays on, for the no-show indicators
    checks_in_since = CASE
        WHEN $1::BOOLEAN OR $2::BOOLEAN OR $5::BOOLEAN
        THEN COALESCE(checks_in_since, NOW())
    END,
    updated_at    = NOW()
WHERE
    facility_id = $8
RETURNING
    printed_qr,
    qr_token,
    entry_code,
    code_secret,
    radius_m,
    flash_booking,
    staff_confirm,
    qr_reader,
    staff_contacts
`

type UpdateFacilityCheckinParams struct {
	PrintedQr     bool            `json:"printed_qr"`
	EntryCode     bool            `json:"entry_code"`
	RadiusM       int32           `json:"radius_m"`
	FlashBooking  bool            `json:"flash_booking"`
	StaffConfirm  bool            `json:"staff_confirm"`
	QrReader      bool            `json:"qr_reader"`
	StaffContacts json.RawMessage `json:"staff_contacts"`
	FacilityID    uuid.UUID       `json:"facility_id"`
}

type UpdateFacilityCheckinRow struct {
	PrintedQr     bool            `json:"printed_qr"`
	QrToken       uuid.UUID       `json:"qr_token"`
	EntryCode     bool            `json:"entry_code"`
	CodeSecret    []byte          `json:"code_secret"`
	RadiusM       int32           `json:"radius_m"`
	FlashBooking  bool            `json:"flash_booking"`
	StaffConfirm  bool            `json:"staff_confirm"`
	QrReader      bool            `json:"qr_reader"`
	StaffContacts json.RawMessage `json:"staff_contacts"`
}

// Row-level security: runs as the facility's council (db.WithTenant).
func (q *Queries) UpdateFacilityCheckin(ctx context.Context, arg UpdateFacilityCheckinParams) (UpdateFacilityCheckinRow, error) {
	row := q.db.QueryRowContext(ctx, updateFacilityCheckin,
		arg.PrintedQr,
		arg.EntryCode,
		arg.RadiusM,
		arg.FlashBooking,
		arg.StaffConfirm,
		arg.QrReader,
		arg.StaffContacts,
		arg.FacilityID,
	)
	var i UpdateFacilityCheckinRow
	err := row.Scan(
		&i.PrintedQr,
		&i.QrToken,
		&i.EntryCode,
		&i.CodeSecret,
		&i.RadiusM,
		&i.FlashBooking,
		&i.StaffConfirm,
		&i.QrReader,
		&i.StaffContacts,
	)
	return i, err
}

const useUserQrToken = `-- name: UseUserQrToken :one
UPDATE user_qr_token q
SET
    used_at = NOW()
FROM
    app_user u
WHERE
    q.token = $1
    AND q.used_at IS NULL
    AND q.expires_at > NOW()
    AND u.id = q.user_id
RETURNING
    q.user_id,
    u.full_name
`

type UseUserQrTokenRow struct {
	UserID   uuid.UUID      `json:"user_id"`
	FullName sql.NullString `json:"full_name"`
}

// A personal QR works once and only until it expires; no row otherwise.
func (q *Queries) UseUserQrToken(ctx context.Context, token uuid.UUID) (UseUserQrTokenRow, error) {
	row := q.db.QueryRowContext(ctx, useUserQrToken, token)
	var i UseUserQrTokenRow
	err := row.Scan(&i.UserID, &i.FullName)
	return i, err
}
